INSERT INTO `nojquery_category_items` (`id`, `category_id`, `item_name`, `description`, `item_type`, `source_file`, `javascript_uncompressed`, `javascript_compressed`, `sort_order`, `active`) VALUES
(1, 2, 'nj(selector)', 'Wählt DOM-Elemente aus oder kapselt vorhandene Elemente.', 'function', 'src/core/nojquery.core.js', 'function nj(selector, context) {\n    if (selector instanceof NJ) return selector;\n    return new NJ(select(selector, context ? nj(context).get() : document));\n  }', 'function nj(selector,context){if(selector instanceof NJ)return selector;return new NJ(select(selector,context?nj(context).get():document));}', 1, 1),
(2, 2, 'each', 'Iteriert über alle ausgewählten Elemente.', 'method', 'src/core/nojquery.core.js', 'each(callback) {\n      if (typeof callback !== \'function\') return this;\n      this.elements.forEach((element, index) => callback.call(element, index, element));\n      return this;\n    }', 'each(callback){if(typeof callback!==\'function\')return this;this.elements.forEach((element,index)=>callback.call(element,index,element));return this;}', 2, 1),
(3, 2, 'map', 'Transformiert die Elementmenge in ein Array.', 'method', 'src/core/nojquery.core.js', 'map(callback) {\n      return this.elements.map((element, index) => callback.call(element, index, element));\n    }', 'map(callback){return this.elements.map((element,index)=>callback.call(element,index,element));}', 3, 1),
(4, 2, 'get', 'Liefert ein Element anhand seines Index.', 'method', 'src/core/nojquery.core.js', 'get(index = 0) {\n      if (index < 0) index = this.elements.length + index;\n      return this.elements[index];\n    }', 'get(index=0){if(index<0)index=this.elements.length+index;return this.elements[index];}', 4, 1),
(5, 2, 'first', 'Liefert das erste Element als NJ-Wrapper.', 'method', 'src/core/nojquery.core.js', 'first() { return new NJ(this.elements.length ? [this.elements[0]] : []); }', 'first(){return new NJ(this.elements.length?[this.elements[0]]:[]);}', 5, 1),
(6, 2, 'last', 'Liefert das letzte Element als NJ-Wrapper.', 'method', 'src/core/nojquery.core.js', 'last() { return new NJ(this.elements.length ? [this.elements[this.elements.length - 1]] : []); }', 'last(){return new NJ(this.elements.length?[this.elements[this.elements.length-1]]:[]);}', 6, 1),
(7, 2, 'eq', 'Liefert ein Element an einer bestimmten Position.', 'method', 'src/core/nojquery.core.js', 'eq(index) {\n      const element = this.get(index);\n      return new NJ(element ? [element] : []);\n    }', 'eq(index){const element=this.get(index);return new NJ(element?[element]:[]);}', 7, 1),
(8, 3, 'find', 'Sucht Nachfahren mit einem CSS-Selektor.', 'method', 'src/core/nojquery.core.js', 'find(selector) {\n      const result = [];\n      this.each(function () { result.push(...select(selector, this)); });\n      return new NJ([...new Set(result)]);\n    }', 'find(selector){const result=[];this.each(function(){result.push(...select(selector,this));});return new NJ([...new Set(result)]);}', 1, 1),
(9, 3, 'closest', 'Sucht den nächsten passenden Vorfahren einschließlich Element.', 'method', 'src/core/nojquery.core.js', 'closest(selector) {\n      const result = this.elements.map(el => el.closest ? el.closest(selector) : null).filter(Boolean);\n      return new NJ([...new Set(result)]);\n    }', 'closest(selector){const result=this.elements.map(el=>el.closest?el.closest(selector):null).filter(Boolean);return new NJ([...new Set(result)]);}', 2, 1),
(10, 3, 'parent', 'Liefert Elternelemente.', 'method', 'src/core/nojquery.core.js', 'parent() {\n      return new NJ([...new Set(this.elements.map(el => el.parentElement).filter(Boolean))]);\n    }', 'parent(){return new NJ([...new Set(this.elements.map(el=>el.parentElement).filter(Boolean))]);}', 3, 1),
(11, 3, 'children', 'Liefert direkte Kindelemente.', 'method', 'src/core/nojquery.core.js', 'children(selector) {\n      let result = [];\n      this.each(function () { result.push(...Array.from(this.children || [])); });\n      if (selector) result = result.filter(el => el.matches(selector));\n      return new NJ(result);\n    }', 'children(selector){let result=[];this.each(function(){result.push(...Array.from(this.children||[]));});if(selector)result=result.filter(el=>el.matches(selector));return new NJ(result);}', 4, 1),
(12, 3, 'next', 'Liefert nächste Geschwisterelemente.', 'method', 'src/core/nojquery.core.js', 'next() { return new NJ(this.elements.map(el => el.nextElementSibling).filter(Boolean)); }', 'next(){return new NJ(this.elements.map(el=>el.nextElementSibling).filter(Boolean));}', 5, 1),
(13, 3, 'prev', 'Liefert vorherige Geschwisterelemente.', 'method', 'src/core/nojquery.core.js', 'prev() { return new NJ(this.elements.map(el => el.previousElementSibling).filter(Boolean)); }', 'prev(){return new NJ(this.elements.map(el=>el.previousElementSibling).filter(Boolean));}', 6, 1),
(14, 4, 'html', 'Liest oder setzt innerHTML.', 'method', 'src/core/nojquery.core.js', 'html(value) {\n      if (value === undefined) return this.get()?.innerHTML;\n      return this.each(function () { this.innerHTML = value; });\n    }', 'html(value){if(value===undefined)return this.get()?.innerHTML;return this.each(function(){this.innerHTML=value;});}', 1, 1),
(15, 4, 'text', 'Liest oder setzt textContent.', 'method', 'src/core/nojquery.core.js', 'text(value) {\n      if (value === undefined) return this.get()?.textContent;\n      return this.each(function () { this.textContent = value; });\n    }', 'text(value){if(value===undefined)return this.get()?.textContent;return this.each(function(){this.textContent=value;});}', 2, 1),
(16, 4, 'val', 'Liest oder setzt den Wert eines Formularelements.', 'method', 'src/core/nojquery.core.js', 'val(value) {\n      if (value === undefined) return this.get()?.value;\n      return this.each(function () { this.value = value; });\n    }', 'val(value){if(value===undefined)return this.get()?.value;return this.each(function(){this.value=value;});}', 3, 1),
(17, 5, 'append', 'Fügt Inhalt am Ende ein.', 'method', 'src/core/nojquery.core.js', 'append(content) { return insertContent(this, content, \'beforeend\'); }', 'append(content){return insertContent(this,content,\'beforeend\');}', 1, 1),
(18, 5, 'prepend', 'Fügt Inhalt am Anfang ein.', 'method', 'src/core/nojquery.core.js', 'prepend(content) { return insertContent(this, content, \'afterbegin\'); }', 'prepend(content){return insertContent(this,content,\'afterbegin\');}', 2, 1),
(19, 5, 'before', 'Fügt Inhalt vor dem Element ein.', 'method', 'src/core/nojquery.core.js', 'before(content) { return insertContent(this, content, \'beforebegin\'); }', 'before(content){return insertContent(this,content,\'beforebegin\');}', 3, 1),
(20, 5, 'after', 'Fügt Inhalt nach dem Element ein.', 'method', 'src/core/nojquery.core.js', 'after(content) { return insertContent(this, content, \'afterend\'); }', 'after(content){return insertContent(this,content,\'afterend\');}', 4, 1),
(21, 5, 'appendTo', 'Hängt die Auswahl an ein Ziel an.', 'method', 'src/core/nojquery.core.js', 'appendTo(target) {\n      const parent = nj(target).get();\n      if (!parent) return this;\n      return this.each(function () { parent.appendChild(this); });\n    }', 'appendTo(target){const parent=nj(target).get();if(!parent)return this;return this.each(function(){parent.appendChild(this);});}', 5, 1),
(22, 5, 'empty', 'Entfernt alle Kindknoten.', 'method', 'src/core/nojquery.core.js', 'empty() { return this.each(function () { this.replaceChildren(); }); }', 'empty(){return this.each(function(){this.replaceChildren();});}', 6, 1),
(23, 5, 'remove', 'Entfernt die Elemente.', 'method', 'src/core/nojquery.core.js', 'remove() { return this.each(function () { this.remove(); }); }', 'remove(){return this.each(function(){this.remove();});}', 7, 1),
(24, 6, 'attr', '', 'method', 'src/core/nojquery.core.js', 'attr(name, value) {\n      if (typeof name === \'object\') {\n        return this.each(function () {\n          Object.entries(name).forEach(([key, val]) => this.setAttribute(key, String(val)));\n        });\n      }\n      if (value === undefined) return this.get()?.getAttribute(name);\n      return this.each(function () { this.setAttribute(name, String(value)); });\n    }', 'attr(name,value){if(typeof name===\'object\'){return this.each(function(){Object.entries(name).forEach(([key,val])=>this.setAttribute(key,String(val)));});}if(value===undefined)return this.get()?.getAttribute(name);return this.each(function(){this.setAttribute(name,String(value));});}', 1, 1),
(25, 6, 'removeAttr', '', 'method', 'src/core/nojquery.core.js', 'removeAttr(name) { return this.each(function () { this.removeAttribute(name); }); }', 'removeAttr(name){return this.each(function(){this.removeAttribute(name);});}', 2, 1),
(26, 6, 'hasAttr', '', 'method', 'src/core/nojquery.core.js', 'hasAttr(name) { return !!this.get()?.hasAttribute(name); }', 'hasAttr(name){return!!this.get()?.hasAttribute(name);}', 3, 1),
(27, 6, 'prop', '', 'method', 'src/core/nojquery.core.js', 'prop(name, value) {\n      if (value === undefined) return this.get()?.[name];\n      return this.each(function () { this[name] = value; });\n    }', 'prop(name,value){if(value===undefined)return this.get()?.[name];return this.each(function(){this[name]=value;});}', 4, 1),
(28, 6, 'data', '', 'method', 'src/core/nojquery.core.js', 'data(name, value) {\n      if (value === undefined) return this.get()?.dataset?.[name];\n      return this.each(function () {\n        if (this.dataset) this.dataset[name] = String(value);\n      });\n    }', 'data(name,value){if(value===undefined)return this.get()?.dataset?.[name];return this.each(function(){if(this.dataset)this.dataset[name]=String(value);});}', 5, 1),
(29, 6, 'removeData', '', 'method', 'src/core/nojquery.core.js', 'removeData(name) {\n      return this.each(function () {\n        if (this.dataset) delete this.dataset[name];\n      });\n    }', 'removeData(name){return this.each(function(){if(this.dataset)delete this.dataset[name];});}', 6, 1),
(30, 7, 'addClass', '', 'method', 'src/core/nojquery.core.js', 'addClass(classes) {\n      const list = String(classes || \'\').split(/\\s+/).filter(Boolean);\n      return this.each(function () { this.classList?.add(...list); });\n    }', 'addClass(classes){const list=String(classes||\'\').split(/\\s+/).filter(Boolean);return this.each(function(){this.classList?.add(...list);});}', 1, 1),
(31, 7, 'removeClass', '', 'method', 'src/core/nojquery.core.js', 'removeClass(classes) {\n      const list = String(classes || \'\').split(/\\s+/).filter(Boolean);\n      return this.each(function () { this.classList?.remove(...list); });\n    }', 'removeClass(classes){const list=String(classes||\'\').split(/\\s+/).filter(Boolean);return this.each(function(){this.classList?.remove(...list);});}', 2, 1),
(32, 7, 'toggleClass', '', 'method', 'src/core/nojquery.core.js', 'toggleClass(name, force) {\n      return this.each(function () {\n        if (!this.classList) return;\n        force === undefined ? this.classList.toggle(name) : this.classList.toggle(name, !!force);\n      });\n    }', 'toggleClass(name,force){return this.each(function(){if(!this.classList)return;force===undefined?this.classList.toggle(name):this.classList.toggle(name,!!force);});}', 3, 1),
(33, 7, 'hasClass', '', 'method', 'src/core/nojquery.core.js', 'hasClass(name) { return !!this.get()?.classList?.contains(name); }', 'hasClass(name){return!!this.get()?.classList?.contains(name);}', 4, 1),
(34, 7, 'css', '', 'method', 'src/core/nojquery.core.js', 'css(property, value) {\n      if (typeof property === \'object\') {\n        return this.each(function () {\n          Object.entries(property).forEach(([key, val]) => {\n            if (key.startsWith(\'--\')) this.style.setProperty(key, val);\n            else this.style[key] = val;\n          });\n        });\n      }\n      if (value === undefined) {\n        const element = this.get();\n        return element ? getComputedStyle(element).getPropertyValue(property) || getComputedStyle(element)[property] : undefined;\n      }\n      return this.each(function () {\n        if (property.startsWith(\'--\')) this.style.setProperty(property, value);\n        else this.style[property] = value;\n      });\n    }', 'css(property,value){if(typeof property===\'object\'){return this.each(function(){Object.entries(property).forEach(([key,val])=>{if(key.startsWith(\'--\'))this.style.setProperty(key,val);else this.style[key]=val;});});}if(value===undefined){const element=this.get();return element?getComputedStyle(element).getPropertyValue(property)||getComputedStyle(element)[property]:undefined;}return this.each(function(){if(property.startsWith(\'--\'))this.style.setProperty(property,value);else this.style[property]=value;});}', 5, 1),
