(39, 9, 'on', 'Registriert direkte oder delegierte Listener.', 'method', 'src/core/nojquery.core.js', 'on(events, selector, handler, options) {\n      if (typeof selector === \'function\') {\n        options = handler;\n        handler = selector;\n        selector = null;\n      }\n      if (typeof handler !== \'function\') return this;\n\n      return this.each(function () {\n        const element = this;\n        String(events).split(/\\s+/).filter(Boolean).forEach(eventName => {\n          const wrapped = selector\n            ? function (event) {\n                const match = event.target.closest(selector);\n                if (match && element.contains(match)) handler.call(match, event);\n              }\n            : handler;\n\n          element.__njEvents ||= [];\n          element.__njEvents.push({ eventName, original: handler, wrapped, selector, options });\n          element.addEventListener(eventName, wrapped, options || false);\n        });\n      });\n    }', 'on(events,selector,handler,options){if(typeof selector===\'function\'){options=handler;handler=selector;selector=null;}if(typeof handler!==\'function\')return this;return this.each(function(){const element=this;String(events).split(/\\s+/).filter(Boolean).forEach(eventName=>{const wrapped=selector?function(event){const match=event.target.closest(selector);if(match&&element.contains(match))handler.call(match,event);}:handler;element.__njEvents||=[];element.__njEvents.push({eventName,original:handler,wrapped,selector,options});element.addEventListener(eventName,wrapped,options||false);});});}', 1, 1),
